import java.util.Scanner;
public class Fib {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long a = 0, b = 1;
        for (int i = 2; i < n; i++) { long t = a + b; a = b; b = t; }
        System.out.println(n <= 2 ? 1 : b);
    }
}
